pub fn gpu_board_power_within(minimum: Watt, maximum: Watt, w: Watt) -> bool {
    ((crate::std_measure::watt_count(w.clone()) >= crate::std_measure::watt_count(minimum)) && (crate::std_measure::watt_count(w.clone()) <= crate::std_measure::watt_count(maximum)))
}

pub fn gpu_board_power_refusal(spec: Rc<GpuBoardPowerSpecification>) -> Option<Rc<GpuBoardRefusal>> {
    match (*spec.clone()).clone() {
    GpuBoardPowerSpecification::RatedBoardPower { rated: _, .. } => std::option::Option::None,
    GpuBoardPowerSpecification::SystemDependentTgp { minimum: lo, maximum: hi, .. } => if (crate::std_measure::watt_count(lo.clone()) > crate::std_measure::watt_count(hi.clone())) {
        Some(Rc::new(GpuBoardRefusal::BoardPowerRangeInverted))
    } else {
        std::option::Option::None
    },
    GpuBoardPowerSpecification::ConfigurableBoardPower { default: d, minimum: lo, maximum: hi, named_points: points, .. } => if (crate::std_measure::watt_count(lo.clone()) > crate::std_measure::watt_count(hi.clone())) {
        Some(Rc::new(GpuBoardRefusal::BoardPowerRangeInverted))
    } else {
        if match d.clone() {
    Some(dv) => !gpu_board_power_within(lo.clone(), hi.clone(), dv.clone()),
    std::option::Option::None => false,
} {
            Some(Rc::new(GpuBoardRefusal::BoardPowerDefaultOutsideRange))
        } else {
            match Rc::new({ let mut __result = Vec::new(); for n in points.iter().cloned() { if !gpu_board_power_within(lo.clone(), hi.clone(), n.power.clone()) { __result.push(n); } } __result }).first().cloned() {
    Some(n) => Some(Rc::new(GpuBoardRefusal::BoardNamedPointOutsideRange {
    name: n.name.clone(),
})),
    std::option::Option::None => std::option::Option::None,
}
        }
    },
}
}

